const checks=dimRows.map(r=>{
  const k=L2K[r[0]], w=+r[1], pctl=parseFloat(r[2]), raw=parseFloat(r[3]), adds=parseFloat(r[4]);
  return {dim:r[0],
    pctlMatchesJSON: Math.abs(pctl-e.norm[k])<0.06,
    rawMatchesJSON:  Math.abs(raw-e.raw[k])<0.1,
    wMatchesSlider:  w===3,
    addsCorrect:     Math.abs(adds - (w*pctl)/wsum) < 0.06 };
});
const sumAdds=dimRows.reduce((s,r)=>s+parseFloat(r[4]),0);
JSON.stringify({
  dimRowCount: dimRows.length,
  wsum, shownScore: shown,
  sumOfAddsColumn: +sumAdds.toFixed(2),
  addsSumsToScore: Math.abs(sumAdds-shown)<0.25,
  allPctlMatch: checks.every(c=>c.pctlMatchesJSON),
  allRawMatch:  checks.every(c=>c.rawMatchesJSON),
  allAddsCorrect: checks.every(c=>c.addsCorrect),
