  const domW=sliders.map(s=>+s.value);
  const domOk=JSON.stringify(domW)===JSON.stringify(c);
  if(!(nameOk&&scoreOk&&domOk)) fails.push({weights:c, domW, nameOk, scoreOk, domOk,
      got:got.map(g=>`${g.l} ${g.s}`), exp:exp.map(g=>`${g.l} ${g.s.toFixed(1)}`)});
}
JSON.stringify({combosTested:n, failures:fails.length, detail:fails.slice(0,3),
  noNaN: !/NaN/.test(document.body.textContent)},null,1);

