const K=window.__DASHBOARD_DATA__.dimensions.map(d=>d.key);
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
const sliders=[...document.querySelectorAll('#sliders input[type=range]')];
const setW=v=>sliders.forEach((s,i)=>{s.value=v[i];s.dispatchEvent(new Event('input',{bubbles:true}));});
const order=()=>[...document.querySelectorAll('.cards .card')]
  .map(c=>c.textContent.replace(/\s+/g,' ').trim().match(/^\d+\s+([A-Za-z0-9_-]+)/)?.[1]).join(',');
const seen=[];
for(let i=0;i<6;i++){
  setW([3,3,3,3,3,3,3]); await sleep(300);          // go away
  setW([5,1,5,1,5,1,5]); await sleep(400);          // come back to the tie case
  seen.push(order());
}
JSON.stringify({
  runs:seen,
  stable: new Set(seen).size===1,
  verdict: new Set(seen).size===1
    ? "Tie-break is STABLE and deterministic across renders - cosmetic only, not a correctness bug"
    : "UNSTABLE - order jitters between identical renders (real bug)"
},null,1);

const D=window.__DASHBOARD_DATA__, K=D.dimensions.map(d=>d.key);
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
// reset to Balanced via the preset button
[...document.querySelectorAll('#presets button')].find(b=>b.textContent.trim()==='Balanced').click();
await sleep(500);
// select card 1 then open "In detail"
[...document.querySelectorAll('.cards .card')][0].click(); await sleep(350);
const tab=[...document.querySelectorAll('button,[role=tab],a,span')].find(n=>n.textContent.trim()==='In detail');
if(tab) tab.click(); await sleep(450);
const L2K={'Feature Delivery':'feature','Reliability':'reliability','Blast Radius':'blast','Review Leverage':'leverage','Review Depth':'depth','Ownership & Bus Factor':'ownership','Agent Leverage':'agent'};
const rows=[...document.querySelectorAll('tr')].map(r=>[...r.children].map(c=>c.textContent.trim()));
const dim=rows.filter(r=>L2K[r[0]]);
const tot=rows.find(r=>r[0].includes('Contribution Score'));
const e=D.engineers.find(x=>x.login==='pauldambra');
const wsum=tot?+tot[1]:null, shown=tot?parseFloat(tot[tot.length-1]):null;
const checks=dim.map(r=>{const k=L2K[r[0]],w=+r[1],p=parseFloat(r[2]),raw=parseFloat(r[3]),adds=parseFloat(r[4]);
  return {dim:r[0], pctlOk:Math.abs(p-e.norm[k])<0.06, rawOk:Math.abs(raw-e.raw[k])<0.1,
          addsOk:Math.abs(adds-(w*p)/wsum)<0.06};});
const sumAdds=dim.reduce((s,r)=>s+parseFloat(r[4]),0);
JSON.stringify({
  tabFound:!!tab, dimRows:dim.length, wsum, shownScore:shown,
  headerRow: rows.find(r=>r[0]==='Dimension'),
  sampleRow: dim[0],
  allPctlMatchJSON: checks.length===7 && checks.every(c=>c.pctlOk),
  allRawMatchJSON:  checks.length===7 && checks.every(c=>c.rawOk),
  allAddsArithmeticOk: checks.length===7 && checks.every(c=>c.addsOk),
  sumOfAdds:+sumAdds.toFixed(2), addsSumsToScore: Math.abs(sumAdds-shown)<0.25,
  failures: checks.filter(c=>!(c.pctlOk&&c.rawOk&&c.addsOk))
},null,1);

